public class JArrayMax {
	public static void main(String[] args) {
		//Khatwa 1: 'Arraf wa ibtida' al-array
		int[] values = {5, 8, 4, 78, 95, 12, 1, 0, 6, 35, 46};
		//Khatwa 2: Ja'al al-qimah al-uwla ka akbar qimah hatta al-aan.
		int maxValue = values[0];
		//Khatwa 3: Tajarub 'abra al-qiyam al-mutabqi'a fi al-array wa qarrir ayyuha hiya al-qimah al-a'la
		for (int i = 1; i < values.length; i++) {
			//Khatwa 3.1: Ta'ayyan idha kana al-'unsur fi al-index i huwa al-qimah al-a'la hatta al-aan
			if (values[i] > maxValue) {
				maxValue = values[i];
			}
		}
		//Khatwa 4: Taba'a al-qimah al-a'la fi al-array
		System.out.println("Al-qimah al-a'la: " + maxValue);
	}
}
